using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Web.Script.Serialization;
public class PairGuard {
 [STAThread] public static void Main(string[] args){if(Environment.GetEnvironmentVariable("ICU_DISPOSABLE_HOST")!="1")return;string dir=args[0];Directory.CreateDirectory(dir);var json=new JavaScriptSerializer();var form=new Form{Text="Paired Foreground Guard",ClientSize=new Size(340,140),StartPosition=FormStartPosition.Manual,Location=new Point(670,500)};var input=new TextBox{Text="guard",AccessibleName="Guard input",Dock=DockStyle.Fill};form.Controls.Add(input);var timer=new Timer{Interval=15};timer.Tick+=(o,e)=>{try{var sample=NativeObserver.Read();File.AppendAllText(Path.Combine(dir,"ownership.jsonl"),json.Serialize(new{foreground=sample.foreground,focus=sample.focus,x=sample.x,y=sample.y,lastInput=sample.lastInput,mono_ms=Stopwatch.GetTimestamp()*1000/Stopwatch.Frequency})+Environment.NewLine);string p=Path.Combine(dir,"guard.json"),tmp=p+".tmp";File.WriteAllText(tmp,json.Serialize(new{pid=Process.GetCurrentProcess().Id,window=form.Handle.ToInt64(),text=input.Text}));if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}catch(Exception error){File.WriteAllText(Path.Combine(dir,"guard-error.txt"),error.Message);}};form.Shown+=(o,e)=>{NativeObserver.FocusGuardForSetup(form.Handle);input.Focus();timer.Start();};Application.Run(form);}
}
